import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  Sequence,
  spring,
  interpolate,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadPlayfair = makeLoadFont('PlayfairDisplay');

// Module-level font loading
const { fontFamily: interFamily } = loadInter();
const { fontFamily: playfairFamily } = loadPlayfair();



export type InstagramHookProps = Record<string, any>;

// --- INLINE SVG COMPONENTS ---

const Sparkle = ({ size, style, color }: { size: number; style?: React.CSSProperties; color: string }) => (
  <svg width={size} height={size} viewBox="0 0 24 24" fill="none" style={style}>
    <path
      d="M12 0C12 0 12 10.5 24 12C12 13.5 12 24 12 24C12 24 12 13.5 0 12C12 10.5 12 0 12 0Z"
      fill={color}
    />
  </svg>
);

const UpwardArrow = ({ size, color, style }: { size: number; color: string; style?: React.CSSProperties }) => (
  <svg
    width={size}
    height={size}
    viewBox="0 0 24 24"
    fill="none"
    stroke={color}
    strokeWidth="3"
    strokeLinecap="round"
    strokeLinejoin="round"
    style={style}
  >
    <path d="M7 17l9.2-9.2M17 17V7H7" />
  </svg>
);

// --- SLIDE COMPONENTS ---

const Slide1: React.FC<{
  text: string;
  durationInFrames: number;
  transitionDuration: number;
  textColor: string;
  accentColor: string;
}> = ({ text, durationInFrames, transitionDuration, textColor, accentColor }) => {
  const frame = useCurrentFrame();
  const { fps, height, width } = useVideoConfig();

  const words = text.split(" ");

  // Exit Animation
  const exitProgress = interpolate(
    frame,
    [durationInFrames, durationInFrames + transitionDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const translateY = interpolate(exitProgress, [0, 1], [0, -height]);

  return (
    <AbsoluteFill
      style={{
        transform: `translateY(${translateY}px)`,
        justifyContent: "center",
        alignItems: "center",
        paddingTop: height * 0.15,
        paddingBottom: height * 0.1,
      }}
    >
      {/* Background Graphic */}
      <AbsoluteFill style={{ justifyContent: "center", alignItems: "center", opacity: 0.15 }}>
        {Array.from({ length: 3 }).map((_, i) => {
          const circleScale = spring({
            fps,
            frame: frame - i * 10,
            config: { damping: 200 },
          });
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                width: width * 0.8,
                height: width * 0.8,
                borderRadius: "50%",
                border: `8px solid ${accentColor}`,
                transform: `scale(${circleScale * (1 + i * 0.5)})`,
                opacity: interpolate(frame, [0, 30], [0, 1 - i * 0.3], { extrapolateRight: "clamp" }),
              }}
            />
          );
        })}
      </AbsoluteFill>

      {/* Text Content */}
      <div
        style={{
          display: "flex",
          flexWrap: "wrap",
          justifyContent: "center",
          gap: "16px",
          width: "85%",
          zIndex: 1,
        }}
      >
        {words.map((word, i) => {
          const wordSpring = spring({
            fps,
            frame: frame - i * 5,
            config: { damping: 12, stiffness: 200 },
          });

          return (
            <span
              key={i}
              style={{
                fontFamily: interFamily,
                fontWeight: 900,
                fontSize: height * 0.06,
                color: textColor,
                transform: `scale(${wordSpring})`,
                opacity: wordSpring,
                textAlign: "center",
                lineHeight: 1.1,
                transition: "none",
                textTransform: "uppercase",
              }}
            >
              {word}
            </span>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

const Slide2: React.FC<{
  text: string;
  durationInFrames: number;
  transitionDuration: number;
  textColor: string;
  accentColor: string;
}> = ({ text, durationInFrames, transitionDuration, textColor, accentColor }) => {
  const frame = useCurrentFrame();
  const { fps, height, width } = useVideoConfig();

  // Enter Animation (from bottom)
  const enterProgress = interpolate(frame, [0, transitionDuration], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const enterY = interpolate(enterProgress, [0, 1], [height, 0]);

  // Exit Animation (to left)
  const exitProgress = interpolate(
    frame,
    [durationInFrames, durationInFrames + transitionDuration],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );
  const exitX = interpolate(exitProgress, [0, 1], [0, -width]);

  const scaleAnim = spring({
    fps,
    frame: frame - transitionDuration,
    config: { damping: 14, stiffness: 100 },
  });

  return (
    <AbsoluteFill
      style={{
        transform: `translate(${exitX}px, ${enterY}px)`,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Sparkles */}
      <AbsoluteFill>
        {Array.from({ length: 6 }).map((_, i) => {
          const randX = random(`x-${i}`) * width;
          const randY = random(`y-${i}`) * height;
          const sparkleScale = spring({
            fps,
            frame: frame - transitionDuration - i * 8,
            config: { damping: 10 },
          });

          return (
            <Sparkle
              key={i}
              size={width * 0.1}
              color={accentColor}
              style={{
                position: "absolute",
                left: randX,
                top: randY,
                transform: `scale(${sparkleScale}) rotate(${frame * 0.5}deg)`,
                opacity: interpolate(sparkleScale, [0, 1], [0, 0.8]),
              }}
            />
          );
        })}
      </AbsoluteFill>

      <div
        style={{
          width: "90%",
          textAlign: "center",
          transform: `scale(${interpolate(scaleAnim, [0, 1], [0.8, 1])})`,
          opacity: interpolate(frame - transitionDuration, [0, 15], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          }),
        }}
      >
        <span
          style={{
            fontFamily: playfairFamily,
            fontWeight: 700,
            fontStyle: "italic",
            fontSize: height * 0.08,
            color: accentColor,
            lineHeight: 1.1,
            transition: "none",
          }}
        >
          {text}
        </span>
      </div>
    </AbsoluteFill>
  );
};

const Slide3: React.FC<{
  text: string;
  transitionDuration: number;
  textColor: string;
  highlightColor: string;
}> = ({ text, transitionDuration, textColor, highlightColor }) => {
  const frame = useCurrentFrame();
  const { fps, height, width } = useVideoConfig();

  // Enter Animation (from right)
  const enterProgress = interpolate(frame, [0, transitionDuration], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const enterX = interpolate(enterProgress, [0, 1], [width, 0]);

  // Split logic to emphasize "$10K" or numbers
  const words = text.split(" ");

  return (
    <AbsoluteFill
      style={{
        transform: `translateX(${enterX}px)`,
        justifyContent: "center",
        alignItems: "center",
        backgroundColor: highlightColor,
      }}
    >
      {/* Background Graphic Lines */}
      <AbsoluteFill style={{ opacity: 0.15, overflow: "hidden" }}>
        {Array.from({ length: 5 }).map((_, i) => {
          const moveY = interpolate(
            frame,
            [0, 150],
            [height + 200, -200 - i * 100]
          );
          return (
            <div
              key={i}
              style={{
                position: "absolute",
                left: width * 0.15 * (i + 1),
                top: moveY,
                width: 20,
                height: height * 1.5,
                backgroundColor: "#ffffff",
                transform: "rotate(30deg)",
              }}
            />
          );
        })}
      </AbsoluteFill>

      {/* Floating Arrows */}
      {Array.from({ length: 4 }).map((_, i) => {
        const arrowSpring = spring({
          fps,
          frame: frame - transitionDuration - i * 10,
          config: { damping: 10 },
        });
        const yPos = interpolate(frame, [0, 120], [0, -200]);
        return (
          <UpwardArrow
            key={`arrow-${i}`}
            size={height * 0.1}
            color="#ffffff"
            style={{
              position: "absolute",
              left: width * 0.2 + random(`ax-${i}`) * width * 0.6,
              top: height * 0.7 + yPos,
              transform: `scale(${arrowSpring})`,
              opacity: interpolate(arrowSpring, [0, 1], [0, 0.4]),
            }}
          />
        );
      })}

      <div
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          width: "90%",
          gap: "20px",
          zIndex: 1,
        }}
      >
        {words.map((word, i) => {
          const isMoney = word.includes("$") || word.match(/\d/);
          const popSpring = spring({
            fps,
            frame: frame - transitionDuration - i * 6,
            config: { damping: 12, stiffness: 150, mass: 1.5 },
          });

          return (
            <span
              key={i}
              style={{
                fontFamily: interFamily,
                fontWeight: 900,
                fontSize: isMoney ? height * 0.12 : height * 0.07,
                color: isMoney ? "#ffffff" : textColor,
                transform: `scale(${popSpring})`,
                opacity: popSpring,
                textAlign: "center",
                lineHeight: 1,
                textTransform: "uppercase",
                textShadow: isMoney ? "0px 10px 20px rgba(0,0,0,0.2)" : "none",
                transition: "none",
              }}
            >
              {word}
            </span>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

// --- MAIN COMPONENT ---

const InstagramHookAnimation: React.FC<InstagramHookProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 6,
  slide1Text = "I created a step by step system",
  slide2Text = "to help beauty providers",
  slide3Text = "hit $10K Plus months!",
  accentColor = "#F472B6",
  highlightColor = "#10B981",
  textColor = "#FFFFFF",
}) => {
  const { fps } = useVideoConfig();

  const totalFrames = Math.floor(durationInSeconds * fps);
  const transitionDuration = 15;

  // Distribute time across 3 slides
  const slide1Duration = Math.floor(totalFrames * 0.35);
  const slide2Duration = Math.floor(totalFrames * 0.35);
  // Slide 3 takes the remainder
  const slide3Duration = totalFrames - slide1Duration - slide2Duration;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, overflow: "hidden" }}>
      {/* Slide 1 overlaps transition into Slide 2 */}
      <Sequence from={0} durationInFrames={slide1Duration + transitionDuration}>
        <Slide1
          text={slide1Text}
          durationInFrames={slide1Duration}
          transitionDuration={transitionDuration}
          textColor={textColor}
          accentColor={accentColor}
        />
      </Sequence>

      {/* Slide 2 overlaps transition into Slide 3 */}
      <Sequence
        from={slide1Duration}
        durationInFrames={slide2Duration + transitionDuration}
      >
        <Slide2
          text={slide2Text}
          durationInFrames={slide2Duration}
          transitionDuration={transitionDuration}
          textColor={textColor}
          accentColor={accentColor}
        />
      </Sequence>

      {/* Slide 3 finishes the sequence */}
      <Sequence
        from={slide1Duration + slide2Duration}
        durationInFrames={slide3Duration}
      >
        <Slide3
          text={slide3Text}
          transitionDuration={transitionDuration}
          textColor={backgroundColor} // Contrasting color for the highlight background
          highlightColor={highlightColor}
        />
      </Sequence>
    </AbsoluteFill>
  );
};

export default InstagramHookAnimation;